pub fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // We only care about the first `n` entries (or fewer, if the vector is shorter).
    let limit = std::cmp::min(n as usize, participations.len());
    // A participant is eligible if (5 - attendance) >= k,
    // i.e. attendance <= 5 - k.
    let threshold = 5u8.saturating_sub(k);

    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&att| att <= threshold)
        .count();

    // Each team needs 3 participants.
    (eligible_count / 3) as u8
}

