    #[test]
    fn example_cases() {
        // If k = 2, threshold = 3. Eligible attendances are [0,3,1] → 3 people → 1 team.
        assert_eq!(solve(5, 2, vec![0, 3, 5, 1, 4]), 1);
        // If n < participations.len(), we only take the first n elements.
        assert_eq!(solve(2, 1, vec![5, 0, 0, 0]), 0); // Only [5,0], threshold=4, eligible only 0 → 1 eligible → 0 teams
        // If list shorter than n, we just take all.
        assert_eq!(solve(10, 0, vec![0, 1, 2, 3, 4, 5]), 2); // threshold=5 → 6 eligible → 2 teams
    }
